// reproducer.js
// This script starts a local HTTP server that never flushes any paintable HTML,
// then runs Lighthouse against it to force a FCP hang and trigger the 60s timeout.

const http = require('http');
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

async function run() {
  // 1) Start a simple server that deliberately never writes closing </body> or any visible content
  const server = http.createServer((req, res) => {
    if (req.url === '/no-fcp') {
      res.writeHead(200, {'Content-Type': 'text/html'});
      // send only head and open body tag, never send any paintable content
      res.write('<!DOCTYPE html><html><head><title>No FCP</title></head><body>');
      // never write '<h1>' so Chrome will never report FCP
      // keep the socket open
    } else {
      res.writeHead(404);
      res.end();
    }
  });

  await new Promise(resolve => server.listen(8080, resolve));
  console.log('Server listening on http://localhost:8080/no-fcp');

  // 2) Launch headless Chrome
  const chrome = await chromeLauncher.launch({
    chromeFlags: ['--headless', '--disable-gpu']
  });

  // 3) Run Lighthouse with default settings (which now waits for FCP)
  try {
    const options = {
      port: chrome.port,
      // shorten timeouts so test finishes quickly
      maxWaitForFcp: 10000,        // this flag was introduced in Lighthouse v6+
      maxWaitForLoad: 10000        // force maxLoad shorter than default 35s
    };

    const runnerResult = await lighthouse(
      'http://localhost:8080/no-fcp',
      options
    );
    console.log('Unexpected success, result:', runnerResult.lhr);
  } catch (err) {
    console.error('Expected timeout error:', err.message || err.code || err);
  } finally {
    await chrome.kill();
    server.close();
  }
}

run().catch(err => console.error(err));
